 h,w=len(grid),len(grid[0])
 # locate 7x7 block of 1s (top-left most rows/cols)
 cells=[(r,c) for r in range(h) for c in range(w) if grid[r][c]==1]
 # bounding exact rows with many ones
 r0=min(r for r,c in cells); c0=min(c for r,c in cells)
 # markers in block
 markers={}
 for r in range(r0,r0+7):
  for c in range(c0,c0+7):
   v=grid[r][c]
   if v not in (0,1): markers[v]=(r-r0,c-c0)
 out=[[0]*7 for _ in range(7)]
 for color,(mr,mc) in markers.items():
  pts=[(r,c) for r in range(h) for c in range(w) if grid[r][c]==color and not (r0<=r<r0+7 and c0<=c<c0+7)]
  if not pts: continue
  ar=min(r for r,c in pts); ac=min(c for r,c in pts)
  # slots determined marker quadrant
  sr=0 if mr<3 else 4; sc=0 if mc<3 else 4
  for r,c in pts:
   rr=sr+(r-ar); cc=sc+(c-ac)
   if 0<=rr<7 and 0<=cc<7: out[rr][cc]=color
 return out"}

