    h,w=len(grid),len(grid[0]); out=[[0]*7 for _ in range(7)]
    # marker colors in the 7x7 key, at the four corners of its inner cross
    slots={}
    for r,c,orow,ocol in [(1,1,0,0),(1,5,0,4),(5,1,4,0),(5,5,4,4)]:
        slots[grid[r][c]]=(orow,ocol)
    # collect cells of each marker color outside key, and normalize their bbox
    for color,(dr,dc) in slots.items():
        cells=[(r,c) for r in range(h) for c in range(w) if not (r<7 and c<7) and grid[r][c]==color]
        if not cells: continue
        r0=min(r for r,c in cells); c0=min(c for r,c in cells)
        for r,c in cells:
            rr=dr+r-r0; cc=dc+c-c0
            if 0<=rr<7 and 0<=cc<7: out[rr][cc]=color
    return out"}

